<?php
declare(strict_types=1);
namespace Corevia\Protocol;
use Corevia\Core\CanonicalJson;

/** Deterministic source generation. Fixed output names; existing hand edits are protected. */
final readonly class ContractGenerator
{
    public function __construct(private ContractManifest $manifest) {}
    private static function quote(string $value): string { return json_encode($value, JSON_THROW_ON_ERROR | JSON_UNESCAPED_SLASHES); }
    public function files(): array
    {
        $json = $this->manifest->json(); $quoted = self::quote($json); $fingerprint = $this->manifest->fingerprint();
        $js = "// Generated by Corevia; edit the source manifest.\nimport { createRuntime } from './runtime.js';\nexport const manifest = JSON.parse($quoted);\nexport const fingerprint = '$fingerprint';\nexport const createClient = transport => createRuntime(manifest, transport);\n";
        $python = "# Generated by Corevia; edit the source manifest. Python 3.11+ types.\nimport json as _json\nfrom typing import Any as _Any, TypedDict as _TypedDict, NotRequired as _NotRequired, Literal as _Literal\nfrom .runtime import Runtime\nmanifest = _json.loads($quoted)\nfingerprint = '$fingerprint'\n";
        $dartQuoted = str_replace('$', '\\$', $quoted);
        $dart = "// Generated by Corevia; edit the source manifest.\nimport 'dart:convert';\nimport 'runtime.dart';\nfinal Map<String,dynamic> manifest = jsonDecode($dartQuoted);\nfinal _compiledManifest = manifest;\nconst fingerprint = '$fingerprint';\n";
        $ts = "// Generated by Corevia; edit the source manifest.\n";
        $data = $this->manifest->data();
        foreach ($this->typeOrder() as $name) {
            $schema = $data['$defs'][$name]; $type = 'Type_' . $name;
            $ts .= 'export type ' . $type . ' = ' . $this->type($schema, 'ts') . ";\n";
            if (($schema['type'] ?? '') === 'object' && !($schema['additionalProperties'] ?? false)) {
                $fields = [];
                foreach ($schema['properties'] ?? [] as $key => $child) { $field = $this->type($child, 'py'); if (!in_array($key, $schema['required'] ?? [], true)) { $field = '_NotRequired[' . $field . ']'; } $fields[] = self::quote($key) . ': ' . $field; }
                $python .= "$type = _TypedDict('$type', {" . implode(', ', $fields) . "})\n";
            } else { $python .= $type . ' = ' . $this->type($schema, 'py') . "\n"; }
            if (($schema['type'] ?? '') === 'object') {
                $schemaKey = self::quote($name);
                $dart .= "class $type {\n  final Map<String,dynamic> _data;\n  $type.fromJson(Map<String,dynamic> value): _data = Map.unmodifiable(value) { validate(manifest, manifest[r'\$defs'][$schemaKey], value); }\n  Map<String,dynamic> toJson() => Map.of(_data);\n";
                $accessors = [];
                foreach ($schema['properties'] ?? [] as $key => $child) {
                    // Prefix field accessors and encode keys as literals; no source identifiers from arbitrary metadata.
                    $accessor = 'field_' . preg_replace('/[^A-Za-z0-9_]/', '_', $key);
                    if (isset($accessors[$accessor])) { throw new \InvalidArgumentException('Property names collide as generated accessors.'); } $accessors[$accessor] = true;
                    $required = in_array($key, $schema['required'] ?? [], true); $fieldType = $this->type($child, 'dart');
                    $expression = '_data[' . self::quote($key) . ']'; $decoded = $this->dartValue($child, $expression);
                    if (!$required) { if (!in_array($fieldType, ['dynamic','Null'], true)) { $fieldType .= '?'; } $decoded = $expression . ' == null ? null : ' . $decoded; }
                    $dart .= '  ' . $fieldType . ' get ' . $accessor . ' => ' . $decoded . ";\n";
                }
                $dart .= "}\n";
            } else { $dart .= 'typedef ' . $type . ' = ' . $this->type($schema, 'dart') . ";\n"; }
        }
        $ts .= "export interface ActionPayloads {\n";
        foreach ($data['actions'] as $name => $definition) { $ts .= '  ' . self::quote($name) . ': ' . $this->type($definition['input'], 'ts') . ";\n"; }
        $ts .= "}\nexport interface ActionResults {\n";
        foreach ($data['actions'] as $name => $definition) { $ts .= '  ' . self::quote($name) . ': ' . $this->type($definition['output'], 'ts') . ";\n"; }
        $ts .= "}\nexport interface EventPayloads {\n";
        foreach ($data['events'] as $name => $definition) { $ts .= '  ' . self::quote($name) . ': ' . $this->type($definition['payload'], 'ts') . ";\n"; }
        $codes = array_map(self::quote(...), array_keys($data['errors'])); $ts .= "}\nexport type ErrorCode = " . ($codes ? implode(' | ', $codes) : 'never') . ";\n";
        $ts .= "export interface AuthRequirement {scheme: string; scopes?: string[]}\nexport interface Client {\n  action<N extends keyof ActionPayloads>(name:N,payload:ActionPayloads[N]):Promise<ActionResults[N]>;\n  validateInput<N extends keyof ActionPayloads>(name:N,value:unknown):ActionPayloads[N];\n  validateOutput<N extends keyof ActionResults>(name:N,value:unknown):ActionResults[N];\n  validateEvent<N extends keyof EventPayloads>(name:N,value:unknown):EventPayloads[N];\n  validateError(name:keyof ActionPayloads,code:ErrorCode,retryable:boolean):void;\n  requirements(name:keyof ActionPayloads):AuthRequirement[];\n}\nexport declare const fingerprint: string;\nexport declare const manifest: Readonly<Record<string, unknown>>;\nexport declare function createClient(transport:(name:string,payload:unknown,auth:AuthRequirement[])=>Promise<unknown>):Client;\n";
        $python .= "\nclass Client(Runtime):\n    def __init__(self, transport):\n        super().__init__(manifest, transport)\n";
        $dart .= "class Client extends Runtime {\n  Client(Future<dynamic> Function(String,dynamic,List<dynamic>) transport):super(_compiledManifest,transport);\n";
        $methods = [];
        foreach ($data['actions'] as $name => $definition) {
            $method = 'action_' . preg_replace('/[^A-Za-z0-9_]/', '_', $name);
            if (isset($methods[$method])) { throw new \InvalidArgumentException('Action names collide as generated methods.'); } $methods[$method] = true;
            $python .= '    def ' . $method . '(self, payload: ' . $this->type($definition['input'], 'py') . ') -> ' . $this->type($definition['output'], 'py') . ":\n        return self.action(" . self::quote($name) . ", payload)\n";
            $inputType = $this->type($definition['input'], 'dart'); $outputType = $this->type($definition['output'], 'dart');
            $payload = $this->dartWire($definition['input'],'payload');
            $dart .= '  Future<' . $outputType . '> ' . $method . '(' . $inputType . ' payload) async { final result = await action(' . self::quote($name) . ', ' . $payload . '); return ' . $this->dartValue($definition['output'], 'result') . "; }\n";
        }
        $dart .= "}\n";
        $phpLiteral = var_export($json, true);
        $php = "<?php\ndeclare(strict_types=1);\n// Generated by Corevia; edit the source manifest.\nreturn static fn (callable \$transport): \\Corevia\\Protocol\\ContractClient => new \\Corevia\\Protocol\\ContractClient(\\Corevia\\Protocol\\ContractManifest::fromArray(json_decode($phpLiteral, true, 64, JSON_THROW_ON_ERROR)), \$transport);\n";
        $templates = dirname(__DIR__) . '/templates/';
        return ['manifest.json' => $json . "\n", 'php/client.php' => $php, 'js/client.js' => $js, 'js/client.d.ts' => $ts, 'js/runtime.js' => file_get_contents($templates . 'runtime.js'), 'js/package.json' => "{\"type\":\"module\"}\n", 'python/__init__.py' => "from .client import Client, manifest, fingerprint\n", 'python/client.py' => $python, 'python/runtime.py' => file_get_contents($templates . 'runtime.py'), 'dart/client.dart' => $dart, 'dart/runtime.dart' => file_get_contents($templates . 'runtime.dart')];
    }
    private function typeOrder(): array
    {
        $defs = $this->manifest->data()['$defs']; $order = []; $seen = [];
        $references = function (array $schema) use (&$references): array { $refs = isset($schema['$ref']) ? [substr($schema['$ref'], 8)] : []; foreach ($schema['properties'] ?? [] as $child) { $refs = [...$refs, ...$references($child)]; } if (isset($schema['items'])) { $refs = [...$refs, ...$references($schema['items'])]; } return $refs; };
        $visit = function (string $name) use (&$visit, &$order, &$seen, $defs, $references): void { if (isset($seen[$name])) { return; } $seen[$name] = true; $refs = $references($defs[$name]); sort($refs, SORT_STRING); foreach ($refs as $ref) { $visit($ref); } $order[] = $name; };
        foreach (array_keys($defs) as $name) { $visit($name); } return $order;
    }
    private function type(array $schema, string $language): string
    {
        if (isset($schema['$ref'])) { return 'Type_' . substr($schema['$ref'], 8); }
        if (isset($schema['enum']) && $language !== 'dart') {
            $values = array_map(static fn ($v): string => $language === 'py' ? ($v === null ? 'None' : (is_bool($v) ? ($v ? 'True' : 'False') : json_encode($v, JSON_THROW_ON_ERROR))) : json_encode($v, JSON_THROW_ON_ERROR), $schema['enum']);
            return $language === 'py' ? '_Literal[' . implode(', ', $values) . ']' : implode(' | ', $values);
        }
        if (is_array($schema['type'])) { $types = array_map(fn (string $type): string => $this->type([...$schema, 'type' => $type], $language), $schema['type']); return $language === 'dart' ? 'dynamic' : implode(' | ', array_unique($types)); }
        $type = $schema['type'];
        if ($type === 'array') { $item = $this->type($schema['items'], $language); return match ($language) { 'ts' => '(' . $item . ')[]', 'py' => 'list[' . $item . ']', default => 'List<' . $item . '>' }; }
        if ($type === 'object') {
            if ($language !== 'ts') { return $language === 'py' ? 'dict[str, _Any]' : 'Map<String,dynamic>'; }
            $fields = []; foreach ($schema['properties'] ?? [] as $key => $child) { $fields[] = self::quote($key) . (in_array($key, $schema['required'] ?? [], true) ? '' : '?') . ': ' . $this->type($child, 'ts'); }
            if ($schema['additionalProperties'] ?? false) { $fields[] = '[key: string]: unknown'; } return '{' . implode('; ', $fields) . '}';
        }
        return match ($language) { 'ts' => match ($type) { 'integer','number' => 'number', 'boolean' => 'boolean', 'null' => 'null', default => 'string' }, 'py' => match ($type) { 'integer' => 'int', 'number' => 'float', 'boolean' => 'bool', 'null' => 'None', default => 'str' }, default => match ($type) { 'integer' => 'int', 'number' => 'num', 'boolean' => 'bool', 'null' => 'Null', default => 'String' } };
    }
    private function dartValue(array $schema, string $expression): string
    {
        if (isset($schema['$ref'])) {
            $name = substr($schema['$ref'],8); $definition = $this->manifest->data()['$defs'][$name];
            return ($definition['type'] ?? '') === 'object' ? 'Type_' . $name . '.fromJson(Map<String,dynamic>.from(' . $expression . '))' : $this->dartValue($definition,$expression);
        }
        if (is_array($schema['type'])) { return $expression; }
        return match($schema['type']) {
            'integer' => '(' . $expression . ' as num).toInt()', 'number' => '(' . $expression . ' as num)', 'boolean' => '(' . $expression . ' as bool)', 'string' => '(' . $expression . ' as String)', 'null' => 'null',
            'object' => 'Map<String,dynamic>.from(' . $expression . ')', 'array' => '(' . $expression . ' as List).map((item) => ' . $this->dartValue($schema['items'],'item') . ').toList()',
        };
    }
    private function dartWire(array $schema, string $expression): string
    {
        if(isset($schema['$ref'])){$definition=$this->manifest->data()['$defs'][substr($schema['$ref'],8)];return ($definition['type']??'')==='object'?$expression.'.toJson()':$this->dartWire($definition,$expression);}
        return ($schema['type']??'')==='array'?'('.$expression.').map((item) => '.$this->dartWire($schema['items'],'item').').toList()':$expression;
    }
    public function write(string $directory, bool $check = false): void
    {
        $files = $this->files(); $marker = '.corevia-contract.json';
        $hashes = []; foreach ($files as $name => $content) { $hashes[$name] = hash('sha256', $content); }
        $ownership = ['format' => 1, 'name' => $this->manifest->data()['name'], 'fingerprint' => $this->manifest->fingerprint(), 'files' => $hashes];
        $files[$marker] = CanonicalJson::encode($ownership) . "\n";
        if ($check) { foreach ($files as $name => $content) { if (!is_file($directory . '/' . $name) || file_get_contents($directory . '/' . $name) !== $content) { throw new \RuntimeException('Generated contracts are missing or stale: ' . $name); } } return; }
        if (is_link($directory)) { throw new \InvalidArgumentException('Generated directory cannot be a symlink.'); }
        $old = is_file($directory . '/' . $marker) ? json_decode(file_get_contents($directory . '/' . $marker), true, 64, JSON_THROW_ON_ERROR) : null;
        if (is_dir($directory) && $old === null && count(scandir($directory)) > 2) { throw new \LogicException('Refusing to overwrite an unowned directory.'); }
        if ($old !== null && ($old['name'] ?? null) !== $ownership['name']) { throw new \LogicException('Directory belongs to another contract.'); }
        foreach ($files as $name => $content) {
            $path = $directory . '/' . $name;
            foreach ([$path, dirname($path)] as $part) { if (is_link($part)) { throw new \InvalidArgumentException('Generated output cannot follow symlinks.'); } }
            if (is_file($path) && $name !== $marker && (!isset($old['files'][$name]) || !hash_equals($old['files'][$name], hash_file('sha256', $path)))) { throw new \LogicException('Generated file was edited; move it before regenerating: ' . $name); }
        }
        foreach ($files as $name => $content) {
            $path = $directory . '/' . $name; if (!is_dir(dirname($path)) && !mkdir(dirname($path), 0755, true) && !is_dir(dirname($path))) { throw new \RuntimeException('Cannot create generated directory.'); }
            $temporary = $path . '.' . bin2hex(random_bytes(8)) . '.tmp';
            try { if (file_put_contents($temporary, $content, LOCK_EX) === false || !rename($temporary, $path)) { throw new \RuntimeException('Cannot save generated contract.'); } }
            finally { if (is_file($temporary)) { unlink($temporary); } }
        }
    }
}
